// Decide who gets emailed on today's run. Emits tagged items:
//   action = "request"  -> job marked Complete at least 1 day ago, never asked
//   action = "followup" -> asked 5+ days ago, follow-up not yet sent
// Status counts as finished when it reads Complete / Completed / Done / Finished
// (any capitalisation). Anything else is dropped silently.
const DAY_MS = 24 * 60 * 60 * 1000;
const now = Date.now();
const doneWords = ['complete', 'completed', 'done', 'finished'];
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  if (!doneWords.includes(String(j['Status'] || '').trim().toLowerCase())) continue;
  const email = String(j['Email'] || '').trim();
  if (!email.includes('@')) continue;
  const completedAt = new Date(j['Completion Date']).getTime();
  if (isNaN(completedAt)) continue;
  const requestSent = String(j['Review Request Sent'] || '').trim();
  const followUpSent = String(j['Follow-Up Sent'] || '').trim();
  if (!requestSent && now - completedAt >= DAY_MS) {
    out.push({ json: { ...j, action: 'request' } });
  } else if (requestSent && !followUpSent) {
    const sentAt = new Date(requestSent).getTime();
    if (!isNaN(sentAt) && now - sentAt >= 5 * DAY_MS) {
      out.push({ json: { ...j, action: 'followup' } });
    }
  }
}
return out;

